import type { Style } from '$lib/types/pdf-components';
import type { PdfcnTheme } from '$lib/types/pdf-themes';

export type GraphStyles = Record<string, Style>;

export const createGraphStyles = (t: PdfcnTheme): GraphStyles => ({
	chartWithRightLegend: { alignItems: 'flex-start', display: 'flex', flexDirection: 'row' },
	container: { display: 'flex', flexDirection: 'column', marginBottom: t.spacing.componentGap },
	legendColumn: {
		display: 'flex', flexDirection: 'column', gap: 8, marginLeft: 12, marginTop: 18, minWidth: 120
	},
	legendItem: { alignItems: 'center', display: 'flex', flexDirection: 'row', gap: 4 },
	legendRow: { display: 'flex', flexDirection: 'row', flexWrap: 'wrap', gap: 12, marginTop: 6 },
	legendText: {
		color: t.colors.mutedForeground,
		fontFamily: t.typography.body.fontFamily,
		fontSize: t.primitives.typography.xs
	},
	subtitle: {
		color: t.colors.mutedForeground,
		fontFamily: t.typography.body.fontFamily,
		fontSize: t.primitives.typography.xs,
		marginBottom: 6
	},
	title: {
		color: t.colors.foreground,
		fontFamily: t.typography.heading.fontFamily,
		fontSize: t.primitives.typography.base,
		fontWeight: t.primitives.fontWeights.semibold,
		marginBottom: 2
	}
});

import type { Style } from '$lib/types/pdf-components';

export interface GraphWidthOptions {
	containerPadding?: number;
	wrapperPadding?: number;
	pageWidth?: number;
}

export type GraphVariant = 'bar' | 'horizontal-bar' | 'line' | 'area' | 'pie' | 'donut';
export type GraphLegendPosition = 'bottom' | 'right' | 'none';

export interface GraphDataPoint {
	label: string;
	value: number;
	color?: string;
}

export interface GraphSeries {
	name: string;
	data: GraphDataPoint[];
	color?: string;
}

export interface GraphProps {
	variant?: GraphVariant;
	data: GraphDataPoint[] | GraphSeries[];
	title?: string;
	subtitle?: string;
	xLabel?: string;
	yLabel?: string;
	width?: number;
	height?: number;
	fullWidth?: boolean;
	containerPadding?: number;
	wrapperPadding?: number;
	colors?: string[];
	showValues?: boolean;
	showGrid?: boolean;
	legend?: GraphLegendPosition;
	centerLabel?: string;
	showDots?: boolean;
	smooth?: boolean;
	yTicks?: number;
	noWrap?: boolean;
	style?: Style;
}

export interface ChartLayout {
	svgW: number;
	svgH: number;
	chartX: number;
	chartY: number;
	chartW: number;
	chartH: number;
	yMin: number;
	yMax: number;
	yTicks: number[];
	xLabels: string[];
}

import type { PdfcnTheme } from '$lib/types/pdf-themes';
import type { ChartLayout, GraphDataPoint, GraphSeries, GraphWidthOptions } from './graph.types';

export const A4_WIDTH = 595;
export const GRAPH_SAFE_WIDTHS = {
	default: 420,
	inSection: 400,
	inSectionWithWrapper: 380
} as const;

export const getGraphWidth = (
	theme: PdfcnTheme,
	options: GraphWidthOptions = {}
): number => {
	const { containerPadding = 0, wrapperPadding = 0, pageWidth = A4_WIDTH } = options;
	const { marginLeft, marginRight } = theme.spacing.page;
	return Math.max(
		Math.floor(pageWidth - marginLeft - marginRight - containerPadding * 2 - wrapperPadding * 2),
		100
	);
};

export const CHART_MARGINS = {
	axisBottom: 24,
	axisLeft: 40,
	pieBottom: 10,
	pieLeft: 10,
	right: 10,
	top: 10
} as const;

export const normalizeData = (data: GraphDataPoint[] | GraphSeries[]): GraphSeries[] => {
	if (data.length === 0) return [];
	if ('label' in data[0] && 'value' in data[0]) {
		return [{ data: data as GraphDataPoint[], name: 'Series 1' }];
	}
	return data as GraphSeries[];
};

export const computeYTicks = (min: number, max: number, count: number): number[] => {
	if (min === max) return [0, max || 1];
	const step = (max - min) / (count - 1);
	return Array.from({ length: count }, (_, i) => Math.round((min + i * step) * 100) / 100);
};

export const fmtNum = (v: number): string => {
	if (Math.abs(v) >= 1_000_000) return `${(v / 1_000_000).toFixed(1)}M`;
	if (Math.abs(v) >= 1000) return `${(v / 1000).toFixed(1)}K`;
	if (!Number.isInteger(v)) return v.toFixed(1);
	return String(v);
};

export const truncate = (s: string, maxLen: number): string =>
	s.length > maxLen ? `${s.slice(0, maxLen - 1)}…` : s;

export const polarToCartesian = (cx: number, cy: number, r: number, angleDeg: number) => {
	const rad = ((angleDeg - 90) * Math.PI) / 180;
	return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
};

export const arcPath = (
	cx: number,
	cy: number,
	r: number,
	startAngle: number,
	endAngle: number,
	innerR = 0
): string => {
	const safeEnd = Math.min(endAngle, startAngle + 359.999);
	const large = safeEnd - startAngle > 180 ? 1 : 0;
	const s = polarToCartesian(cx, cy, r, safeEnd);
	const e = polarToCartesian(cx, cy, r, startAngle);
	if (innerR === 0) {
		return `M ${cx} ${cy} L ${s.x} ${s.y} A ${r} ${r} 0 ${large} 0 ${e.x} ${e.y} Z`;
	}
	const si = polarToCartesian(cx, cy, innerR, safeEnd);
	const ei = polarToCartesian(cx, cy, innerR, startAngle);
	return [
		`M ${s.x} ${s.y}`,
		`A ${r} ${r} 0 ${large} 0 ${e.x} ${e.y}`,
		`L ${ei.x} ${ei.y}`,
		`A ${innerR} ${innerR} 0 ${large} 1 ${si.x} ${si.y}`,
		'Z'
	].join(' ');
};

export const smoothPath = (
	points: { x: number; y: number }[],
	tension = 0.4
): string => {
	if (points.length < 2) return '';
	if (points.length === 2) return `M ${points[0].x} ${points[0].y} L ${points[1].x} ${points[1].y}`;
	const parts = [`M ${points[0].x} ${points[0].y}`];
	for (let i = 0; i < points.length - 1; i += 1) {
		const p0 = points[Math.max(i - 1, 0)];
		const p1 = points[i];
		const p2 = points[i + 1];
		const p3 = points[Math.min(i + 2, points.length - 1)];
		parts.push(
			`C ${p1.x + (p2.x - p0.x) * tension} ${p1.y + (p2.y - p0.y) * tension} ${p2.x - (p3.x - p1.x) * tension} ${p2.y - (p3.y - p1.y) * tension} ${p2.x} ${p2.y}`
		);
	}
	return parts.join(' ');
};

export const getDefaultPalette = (t: PdfcnTheme): string[] => [
	t.colors.primary,
	t.colors.info ?? '#3B82F6',
	t.colors.success ?? '#22C55E',
	t.colors.warning ?? '#F59E0B',
	t.colors.destructive ?? '#EF4444',
	'#8B5CF6',
	'#F97316',
	'#14B8A6'
];

export const buildLayout = (
	series: GraphSeries[],
	width: number,
	height: number,
	isPieOrDonut: boolean,
	yTickCount: number
): ChartLayout => {
	const mL = isPieOrDonut ? CHART_MARGINS.pieLeft : CHART_MARGINS.axisLeft;
	const mB = isPieOrDonut ? CHART_MARGINS.pieBottom : CHART_MARGINS.axisBottom;
	const chartX = mL;
	const chartY = CHART_MARGINS.top;
	const chartW = width - mL - CHART_MARGINS.right;
	const chartH = height - CHART_MARGINS.top - mB;
	const allValues = series.flatMap((item) => item.data.map((point) => point.value));
	const rawMin = Math.min(...allValues, 0);
	const rawMax = Math.max(...allValues, 1);
	const yMin = Math.min(0, rawMin);
	const yMax = rawMax + (rawMax - yMin) * 0.08;
	return {
		chartH,
		chartW,
		chartX,
		chartY,
		svgH: height,
		svgW: width,
		xLabels: series[0]?.data.map((point) => point.label) ?? [],
		yMax,
		yMin,
		yTicks: computeYTicks(yMin, yMax, yTickCount)
	};
};
